cat /home/ubuntu/.claude-account-2/projects/-home-ubuntu--agent-ml-research-idea-gen-0509-4-projects-trace-verdict-study/d40d98be-2346-4614-8601-f2be8b3e831f/tool-results/mcp-agent-ml-research-read_registry-1778958692272.txt | python3 -c "
import json, sys

data = json.loads(sys.stdin.read())
result = json.loads(data['result'])
experiments = result['data']['experiments']

print(f'Total DONE experiments: {len(experiments)}')
print()

# Extract structured data
rows = []
for exp_id, exp in experiments.items():
    spec = exp.get('spec', {})
    metrics = exp.get('metrics', {})

    # Determine model
    model_name = spec.get('model_name', '')
    model_path = spec.get('model_path', spec.get('command', ''))

    if not model_name:
        if 'CodeLlama-13b' in model_path or 'codellama13b' in exp_id:
            model_name = 'CodeLlama-13B'
        elif 'DeepSeek' in model_path or 'deepseek' in exp_id:
            model_name = 'DeepSeek-Coder-7B'
        elif 'Qwen2.5-Coder-7B' in model_path or ('qwen' in exp_id.lower() and '1.5' not in exp_id):
            model_name = 'Qwen-7B'
        elif 'Qwen2.5-Coder-1.5B' in model_path or '1.5b' in exp_id.lower():
            model_name = 'Qwen-1.5B'
        else:
            model_name = 'Unknown'

    # Normalize model name
    if 'Qwen2.5-Coder-7B' in model_name:
        model_name = 'Qwen-7B'
    elif 'Qwen2.5-Coder-1.5B' in model_name:
        model_name = 'Qwen-1.5B'
    elif 'CodeLlama' in model_name:
        model_name = 'CodeLlama-13B'
    elif 'DeepSeek' in model_name:
        model_name = 'DeepSeek-Coder-7B'

    # Determine condition
    condition = ''
    for c in ['exception_only_nomarker', 'exception_only', 'full_trace', 'no_trace', 'label_only', 'ae_only', 'loop_only', 'vota']:
        if c in exp_id:
            condition = c
            break

    # Seed
    seed = spec.get('seed', '')
    if not seed:
        for s in ['seed42', 'seed123', 'seed456']:
            if s in exp_id:
                seed = int(s.replace('seed', ''))
                break

    acc = metrics.get('accuracy', None)

    rows.append({
        'exp_id': exp_id,
        'model': model_name,
        'condition': condition,
        'seed': seed,
        'accuracy': acc,
        'metrics': metrics
    })

# Sort and print
rows.sort(key=lambda x: (x['model'], x['condition'], str(x['seed'])))
for r in rows:
    acc_str = f\"{r['accuracy']*100:.2f}%\" if r['accuracy'] else 'N/A'
    print(f\"{r['exp_id']:45s} | {r['model']:20s} | {r['condition']:25s} | seed={str(r['seed']):4s} | acc={acc_str}\")
" 2>&1

